import { execFileSync } from 'node:child_process'
import { readFile } from 'node:fs/promises'
import { expect, test } from '@playwright/test'

test('subtitle lanes render simultaneous cues, Undo once and survive native project reopen', async ({ page, request }) => {
  const registration = await request.post('/api/auth/register', { data: { username: 'caption-lanes-browser', password: 'caption-lanes-browser-password' } })
  expect(registration.status()).toBe(201)
  const { token } = await registration.json()
  await page.addInitScript(value => localStorage.setItem('caption-lanes-token', value), token)
  const errors: string[] = []
  page.on('pageerror', error => errors.push(error.message))
  await page.goto('/e2e/fixtures/caption-lanes.html')
  const documentOutput = page.getByLabel('Caption document', { exact: true })
  const before = await documentOutput.innerText()
  const subtitles = page.locator('details').filter({ has: page.locator('summary', { hasText: 'Субтитры SRT / VTT / ASS / TXT' }) }).first()
  await subtitles.locator('summary').click()
  await subtitles.locator('input[type=file]').setInputFiles({ name: 'overlapping.srt', mimeType: 'application/x-subrip', buffer: Buffer.from('1\n00:00:00,000 --> 00:00:04,000\nLong caption\n\n2\n00:00:01,000 --> 00:00:02,000\nInner caption\n\n3\n00:00:02,000 --> 00:00:03,000\nAdjacent caption') })
  await expect.poll(async () => JSON.parse(await documentOutput.innerText()).tracks.length).toBe(2)
  const packed = JSON.parse(await documentOutput.innerText())
  expect(packed.tracks.map((track: { clips: { text: string }[] }) => track.clips.map(clip => clip.text))).toEqual([['Long caption'], ['Inner caption', 'Adjacent caption']])
  expect(packed.metadata.captionTextTracks).toEqual(packed.tracks.map((track: { id: string }) => track.id))
  const seek = async (value: number) => page.getByLabel('Плейхед', { exact: true }).evaluate((element, time) => {
    const input = element as HTMLInputElement
    input.value = String(time)
    input.dispatchEvent(new Event('input', { bubbles: true }))
  }, value)
  await seek(1_500_000)
  await expect(page.locator('.composition-text-layer')).toHaveText(['Long caption', 'Inner caption'])
  await seek(2_000_000)
  await expect(page.locator('.composition-text-layer')).toHaveText(['Long caption', 'Adjacent caption'])
  await page.getByRole('button', { name: 'Undo', exact: true }).click()
  expect(await documentOutput.innerText()).toBe(before)
  await expect(page.locator('.composition-text-layer')).toHaveCount(0)
  await page.getByRole('button', { name: 'Redo', exact: true }).click()
  expect(JSON.parse(await documentOutput.innerText())).toEqual(packed)
  const savedResponse = page.waitForResponse(response => new URL(response.url()).pathname === '/api/composition-projects' && response.request().method() === 'POST')
  await page.getByRole('button', { name: 'Save project', exact: true }).click()
  expect((await savedResponse).status()).toBe(201)
  await expect(page.getByLabel('Caption save error')).toHaveText('')
  await page.reload()
  await page.getByRole('button', { name: 'Reopen project', exact: true }).click()
  await expect.poll(async () => JSON.parse(await documentOutput.innerText()).metadata?.captionTextTracks).toEqual(packed.metadata.captionTextTracks)
  expect(JSON.parse(await documentOutput.innerText())).toEqual(packed)
  await seek(1_500_000)
  await expect(page.locator('.composition-text-layer')).toHaveText(['Long caption', 'Inner caption'])
  await expect(page.getByLabel('Caption save error')).toHaveText('')
  await subtitles.locator('summary').click()
  for (const format of ['SRT', 'VTT']) {
    const downloading = page.waitForEvent('download')
    await page.getByRole('button', { name: `Все субтитры · ${format}`, exact: true }).click()
    const download = await downloading
    expect(download.suggestedFilename()).toMatch(new RegExp(`\\.${format.toLowerCase()}$`))
    const path = await download.path()
    expect(path).toBeTruthy()
    const body = await readFile(path!, 'utf8')
    expect(body).toContain('Long caption')
    expect(body).toContain('Inner caption')
    expect(body).toContain('Adjacent caption')
    expect(body.match(/ --> /g)).toHaveLength(3)
    expect(body).toContain(format === 'SRT' ? '00:00:01,000 --> 00:00:02,000' : '00:00:01.000 --> 00:00:02.000')
    expect(JSON.parse(await documentOutput.innerText())).toEqual(packed)
  }
  const mcpToken = process.env.VIDEO_KADR_MCP_TOKEN
  const backend = process.env.REAL_COMPOSITION_BACKEND_URL
  if (!mcpToken || !backend) throw new Error('MCP token and real backend URL are required for caption export qualification')
  await page.locator('summary', {hasText:'Агент и история'}).click()
  await page.getByLabel('Ключ подключения').fill(mcpToken)
  await page.getByRole('button', {name:'Подключить агента',exact:true}).click()
  await expect.poll(async () => (await (await request.get('/api/agent/status', {headers:{Authorization:`Bearer ${mcpToken}`}})).json()).connected).toBe(true)
  let rpcId = 0
  const rpc = async (name: string, args: Record<string, unknown>) => {
    const response = await request.post(`${backend}/mcp`, {headers:{Authorization:`Bearer ${mcpToken}`},data:{jsonrpc:'2.0',id:++rpcId,method:'tools/call',params:{name,arguments:args}}})
    expect(response.status()).toBe(200)
    const envelope = await response.json()
    expect(envelope.result.isError).toBeFalsy()
    return JSON.parse(envelope.result.content[0].text)
  }
  await rpc('create_checkpoint',{label:'Ordinary point'})
  expect(await rpc('list_checkpoints',{})).toMatchObject([{label:'Ordinary point',actor:'mcp-client'}])
  const historyBefore = await rpc('get_history', {})
  for (const format of ['srt', 'vtt']) {
    const exported = await rpc('export_captions', {format})
    expect(exported).toMatchObject({format,cues:3})
    expect(exported.body).toContain('Inner caption')
    expect(exported.body.match(/ --> /g)).toHaveLength(3)
  }
  const single = await rpc('export_captions', {format:'srt',track_id:packed.metadata.captionTextTracks[1]})
  expect(single.cues).toBe(2)
  expect(single.body).not.toContain('Long caption')
  expect(await rpc('get_history', {})).toEqual(historyBefore)
  expect(JSON.parse(await documentOutput.innerText())).toEqual(packed)
  const restyleRevision = (await rpc('get_project', {})).revision
  const restyled = await rpc('restyle_captions', {expectedRevision:restyleRevision,layer_ids:[packed.tracks[1].clips[0].id],font_size_px:72,outline_width:3})
  expect(restyled).toMatchObject({captions:3,restyled:1})
  const styled = JSON.parse(await documentOutput.innerText())
  expect(styled.tracks[1].clips[0].style).toMatchObject({fontSizePx:72,strokeWidthPx:3,strokeColor:'#000000FF'})
  expect(styled.tracks[0]).toEqual(packed.tracks[0])
  await rpc('undo', {})
  expect(JSON.parse(await documentOutput.innerText())).toEqual(packed)
  const secondLane = packed.tracks[1]
  const current = await rpc('get_project', {})
  const merged = await rpc('merge_captions', {expectedRevision:current.revision,layer_ids:secondLane.clips.map((clip:{id:string})=>clip.id).reverse()})
  expect(merged).toMatchObject({layer_id:secondLane.clips[0].id,t_start_us:1_000_000,t_end_us:3_000_000,content:'Inner caption\nAdjacent caption',merged:2})
  await seek(1_500_000)
  await expect(page.locator('.composition-text-layer')).toHaveText(['Long caption','Inner caption\nAdjacent caption'])
  await rpc('undo', {})
  expect(JSON.parse(await documentOutput.innerText())).toEqual(packed)
  await page.getByRole('button',{name:'Clear selection',exact:true}).click()
  await page.getByRole('button',{name:'Select cue Inner caption',exact:true}).click()
  await page.getByRole('button',{name:'Select cue Adjacent caption',exact:true}).click()
  await page.getByRole('button',{name:'Объединить выбранные субтитры',exact:true}).click()
  await expect.poll(async()=>JSON.parse(await documentOutput.innerText()).tracks[1].clips.length).toBe(1)
  await expect(page.locator('.composition-text-layer')).toHaveText(['Long caption','Inner caption\nAdjacent caption'])
  await page.getByRole('button',{name:'Undo',exact:true}).click()
  expect(JSON.parse(await documentOutput.innerText())).toEqual(packed)
  await subtitles.locator('input[type=file]').setInputFiles({ name: 'reuse.vtt', mimeType: 'text/vtt', buffer: Buffer.from('WEBVTT\n\n00:04.000 --> 00:05.000\nReused after reopen') })
  await expect.poll(async () => JSON.parse(await documentOutput.innerText()).tracks[0].clips.length).toBe(2)
  const reused = JSON.parse(await documentOutput.innerText())
  expect(reused.tracks).toHaveLength(2)
  expect(reused.metadata.captionTextTracks).toEqual(packed.metadata.captionTextTracks)
  await seek(4_000_000)
  await expect(page.locator('.composition-text-layer')).toHaveText(['Reused after reopen'])
  await page.getByRole('button', { name: 'Undo', exact: true }).click()
  expect(JSON.parse(await documentOutput.innerText())).toEqual(packed)
  await page.getByRole('button',{name:'Open nested captions',exact:true}).click()
  const nestedOutput = page.getByLabel('Nested caption document', {exact:true})
  const nestedBefore = JSON.parse(await nestedOutput.innerText())
  await page.locator('summary', {hasText:'Оформление субтитров проекта'}).click()
  await page.getByLabel('Размер субтитров',{exact:true}).fill('66')
  const validating = page.waitForResponse(response=>new URL(response.url()).pathname==='/api/compositions/nested-durations')
  await page.getByRole('button',{name:'Применить оформление субтитров',exact:true}).click()
  expect((await validating).status()).toBe(200)
  await expect(page.getByLabel('Nested caption history')).toHaveText('1')
  const nestedStyled = JSON.parse(await nestedOutput.innerText())
  for(const composition of Object.values(nestedStyled.compositions) as {content:{tracks:{kind:string;clips:{style:{fontSize:number}}[]}[]}}[]) for(const track of composition.content.tracks) if(track.kind==='text') for(const clip of track.clips) expect(clip.style.fontSize).toBe(66)
  await expect(page.getByLabel('Nested caption error')).toHaveText('')
  await page.getByRole('button',{name:'Undo nested captions',exact:true}).click()
  expect(JSON.parse(await nestedOutput.innerText())).toEqual(nestedBefore)
  const nestedHistoryBeforeExport = await page.getByLabel('Nested caption history').innerText()
  const rootCaptions = await rpc('export_captions',{format:'srt'})
  expect(rootCaptions.cues).toBe(3)
  expect(rootCaptions.body).toContain('root: Long caption')
  expect(rootCaptions.body).not.toContain('unused:')
  const unusedCaptions = await rpc('export_captions',{format:'vtt',composition_id:'unused'})
  expect(unusedCaptions.cues).toBe(3)
  expect(unusedCaptions.body).toContain('unused: Long caption')
  expect(unusedCaptions.body).not.toContain('root:')
  await page.getByRole('button',{name:'Show unused captions',exact:true}).click()
  for(const format of ['SRT','VTT']) {
    const downloading = page.waitForEvent('download')
    await page.getByRole('button',{name:`Субтитры активной композиции · ${format}`,exact:true}).click()
    const download = await downloading
    expect(download.suggestedFilename()).toContain('unused')
    const body = await readFile((await download.path())!, 'utf8')
    expect(body).toContain('unused: Long caption')
    expect(body).not.toContain('root:')
    expect(body.match(/ --> /g)).toHaveLength(3)
  }
  expect(JSON.parse(await nestedOutput.innerText())).toEqual(nestedBefore)
  expect(await page.getByLabel('Nested caption history').innerText()).toBe(nestedHistoryBeforeExport)
  const unusedLane = nestedBefore.compositions.unused.content.tracks[1]
  for(const clip of unusedLane.clips) await page.locator(`input[data-clip-id="${clip.id}"]`).check()
  const mergeValidation = page.waitForResponse(response=>new URL(response.url()).pathname==='/api/compositions/nested-durations')
  await page.getByRole('button',{name:'Объединить субтитры вложенной композиции',exact:true}).click()
  expect((await mergeValidation).status()).toBe(200)
  await expect.poll(async()=>JSON.parse(await nestedOutput.innerText()).compositions.unused.content.tracks[1].clips.length).toBe(1)
  const nativeMerged = JSON.parse(await nestedOutput.innerText())
  expect(nativeMerged.compositions.unused.content.tracks[1].clips[0]).toEqual({...unusedLane.clips[0],timelineEndTick:3_000_000,text:'unused: Inner caption\nunused: Adjacent caption'})
  expect(nativeMerged.compositions.root).toEqual(nestedBefore.compositions.root)
  expect(JSON.parse(await documentOutput.innerText())).toEqual(packed)
  await page.getByRole('button',{name:'Undo nested captions',exact:true}).click()
  expect(JSON.parse(await nestedOutput.innerText())).toEqual(nestedBefore)
  await expect(page.getByLabel('Nested caption error')).toHaveText('')
  const beforeImport = JSON.parse(await nestedOutput.innerText())
  const importValidation = page.waitForResponse(response=>new URL(response.url()).pathname==='/api/compositions/nested-durations')
  await page.getByLabel('Импорт субтитров вложенной композиции',{exact:true}).setInputFiles({name:'nested-overlap.vtt',mimeType:'text/vtt',buffer:Buffer.from('WEBVTT\n\n00:01.125 --> 00:01.875\nImported nested cue')})
  expect((await importValidation).status()).toBe(200)
  await expect.poll(async()=>JSON.parse(await nestedOutput.innerText()).compositions.unused.content.tracks.length).toBe(3)
  const nativeImported = JSON.parse(await nestedOutput.innerText())
  expect(nativeImported.compositions.unused.content.tracks[2].clips[0]).toMatchObject({timelineStartTick:1_125_000,timelineEndTick:1_875_000,text:'Imported nested cue'})
  expect(nativeImported.compositions.root).toEqual(beforeImport.compositions.root)
  expect(JSON.parse(await documentOutput.innerText())).toEqual(packed)
  const importedExport = await rpc('export_captions',{format:'vtt',composition_id:'unused'})
  expect(importedExport.cues).toBe(4)
  expect(importedExport.body).toContain('00:00:01.125 --> 00:00:01.875\nImported nested cue')
  await page.getByRole('button',{name:'Undo nested captions',exact:true}).click()
  expect(JSON.parse(await nestedOutput.innerText())).toEqual(beforeImport)
  const nestedAgentBefore = await rpc('get_project',{})
  expect(nestedAgentBefore.kind).toBe('nested')
  expect(nestedAgentBefore.projectHash).toMatch(/^[a-f0-9]{64}$/)
  expect(nestedAgentBefore.document).toEqual(beforeImport)
  const nativeAgentMerge = await rpc('merge_captions',{expectedProjectHash:nestedAgentBefore.projectHash,layer_ids:unusedLane.clips.map((clip:{id:string})=>clip.id).reverse()})
  expect(nativeAgentMerge).toMatchObject({kind:'nested',merged:2,content:'unused: Inner caption\nunused: Adjacent caption'})
  expect(nativeAgentMerge.projectHash).not.toBe(nestedAgentBefore.projectHash)
  const afterAgentMerge = JSON.parse(await nestedOutput.innerText())
  expect(afterAgentMerge.compositions.unused.content.tracks[1].clips).toHaveLength(1)
  const staleResponse = await request.post(`${backend}/mcp`,{headers:{Authorization:`Bearer ${mcpToken}`},data:{jsonrpc:'2.0',id:++rpcId,method:'tools/call',params:{name:'restyle_captions',arguments:{expectedProjectHash:nestedAgentBefore.projectHash,font_size_px:99}}}})
  expect((await staleResponse.json()).result.isError).toBe(true)
  expect(JSON.parse(await nestedOutput.innerText())).toEqual(afterAgentMerge)
  expect(await rpc('get_history',{})).toMatchObject({kind:'nested',undoCount:1})
  const nestedUndone = await rpc('undo',{})
  expect(nestedUndone.projectHash).not.toBe(nestedAgentBefore.projectHash)
  expect(JSON.parse(await nestedOutput.innerText())).toEqual(beforeImport)
  const nativeAgentStyle = await rpc('restyle_captions',{expectedProjectHash:nestedUndone.projectHash,font_size_px:88})
  expect(nativeAgentStyle).toMatchObject({kind:'nested',captions:9,restyled:9})
  const afterAgentStyle = JSON.parse(await nestedOutput.innerText())
  expect(afterAgentStyle.compositions.child.content.tracks[0].clips[0].style.fontSize).toBe(88)
  await rpc('undo',{})
  expect(JSON.parse(await nestedOutput.innerText())).toEqual(beforeImport)
  await rpc('redo',{})
  expect(JSON.parse(await nestedOutput.innerText())).toEqual(afterAgentStyle)
  await rpc('undo',{})
  expect(JSON.parse(await nestedOutput.innerText())).toEqual(beforeImport)
  expect(JSON.parse(await documentOutput.innerText())).toEqual(packed)
  const nativeFrame = async (project: typeof nativeImported, timeUs: number) => {
    const response = await request.post('/api/compositions/nested-preview',{headers:{Authorization:`Bearer ${token}`},data:{project,compositionId:'unused',timeUs,renderedOutputs:{}}})
    expect(response.status()).toBe(200)
    const width=Number(response.headers()['x-frame-width']),height=Number(response.headers()['x-frame-height'])
    const frame=await response.body()
    expect(frame.length).toBe(width*height*4)
    return frame
  }
  const withoutImported = structuredClone(nativeImported)
  withoutImported.compositions.unused.content.tracks[2].hidden=true
  expect((await nativeFrame(nativeImported,1_124_999)).equals(await nativeFrame(withoutImported,1_124_999))).toBe(true)
  expect((await nativeFrame(nativeImported,1_125_000)).equals(await nativeFrame(withoutImported,1_125_000))).toBe(false)
  expect((await nativeFrame(nativeImported,1_875_000)).equals(await nativeFrame(withoutImported,1_875_000))).toBe(true)
  const noSecondLane = structuredClone(beforeImport)
  noSecondLane.compositions.unused.content.tracks[1].hidden=true
  expect((await nativeFrame(beforeImport,1_500_000)).equals(await nativeFrame(noSecondLane,1_500_000))).toBe(false)
  const noFirstLane = structuredClone(beforeImport)
  noFirstLane.compositions.unused.content.tracks[0].hidden=true
  expect((await nativeFrame(beforeImport,1_500_000)).equals(await nativeFrame(noFirstLane,1_500_000))).toBe(false)
  const onlyInner = structuredClone(beforeImport)
  onlyInner.compositions.unused.content.tracks[1].clips=[unusedLane.clips[0]]
  expect((await nativeFrame(beforeImport,1_999_999)).equals(await nativeFrame(onlyInner,1_999_999))).toBe(true)
  const onlyAdjacent = structuredClone(beforeImport)
  onlyAdjacent.compositions.unused.content.tracks[1].clips=[unusedLane.clips[1]]
  expect((await nativeFrame(beforeImport,2_000_000)).equals(await nativeFrame(onlyAdjacent,2_000_000))).toBe(true)
  expect((await nativeFrame(beforeImport,1_500_000)).equals(await nativeFrame(afterAgentStyle,1_500_000))).toBe(false)
  const emptyCaptions = structuredClone(beforeImport)
  emptyCaptions.compositions.unused.content.tracks.forEach((track:{hidden:boolean})=>{track.hidden=true})
  expect((await nativeFrame(beforeImport,4_000_000)).equals(await nativeFrame(emptyCaptions,4_000_000))).toBe(true)
  const exportFrames = async (project: typeof nativeImported, startUs: number, endUs: number) => {
    const response = await request.post('/api/compositions/nested-export',{headers:{Authorization:`Bearer ${token}`},data:{schemaVersion:1,mode:'video_only',project,compositionId:'unused',startUs,endUs,renderedOutputs:{}}})
    expect(response.status()).toBe(202)
    const {jobId}=await response.json()
    let terminal:{status:string;error?:string;result?:{url:string;videoCodec:string}}|undefined
    await expect.poll(async()=>{
      const job=await request.get(`/api/jobs/${jobId}`,{headers:{Authorization:`Bearer ${token}`}})
      expect(job.status()).toBe(200)
      terminal=await job.json()
      return terminal!.status
    },{timeout:30_000}).toBe('done')
    expect(terminal!.result!.videoCodec).toBe('ffv1')
    const movie=await request.get(terminal!.result!.url,{headers:{Authorization:`Bearer ${token}`}})
    expect(movie.status()).toBe(200)
    return execFileSync('ffmpeg',['-v','error','-i','pipe:0','-map','0:v:0','-f','rawvideo','-pix_fmt','rgba','pipe:1'],{input:await movie.body(),maxBuffer:64*1024*1024,timeout:30_000})
  }
  for(const timeUs of [1_125_000,1_875_000,2_000_000]) {
    const decoded=await exportFrames(nativeImported,timeUs,timeUs+1)
    const preview=await nativeFrame(nativeImported,timeUs)
    expect(decoded.length).toBe(preview.length)
    expect(decoded.equals(preview)).toBe(true)
  }
  const sequence = structuredClone(nativeImported)
  Object.assign(sequence.compositions.unused.content.canvas,{width:320,height:180,fpsMilli:10_000})
  delete sequence.compositions.unused.content.canvas.fpsRate
  const sequenceFrames=await exportFrames(sequence,0,5_000_000),frameBytes=320*180*4
  expect(sequenceFrames.length).toBe(frameBytes*50)
  for(const frame of [0,10,11,12,18,19,20,29,30,39,40,49]) {
    expect(sequenceFrames.subarray(frame*frameBytes,(frame+1)*frameBytes).equals(await nativeFrame(sequence,frame*100_000))).toBe(true)
  }
  const textEditor=page.locator(`[data-caption-editor="${unusedLane.clips[0].id}"]`)
  await textEditor.locator('summary').click()
  const textInput=textEditor.getByLabel('Текст субтитра',{exact:true})
  await expect(textInput).toHaveValue('unused: Inner caption')
  const corrected='Исправлено <&>\nSecond line'
  await textInput.fill(corrected)
  const textValidation=page.waitForResponse(response=>new URL(response.url()).pathname==='/api/compositions/nested-durations')
  await textEditor.getByRole('button',{name:'Сохранить текст',exact:true}).click()
  expect((await textValidation).status()).toBe(200)
  await expect.poll(async()=>JSON.parse(await nestedOutput.innerText()).compositions.unused.content.tracks[1].clips[0].text).toBe(corrected)
  const correctedProject=JSON.parse(await nestedOutput.innerText())
  expect(correctedProject.compositions.unused.content.tracks[1].clips[0]).toEqual({...unusedLane.clips[0],text:corrected})
  expect(correctedProject.compositions.root).toEqual(beforeImport.compositions.root)
  const correctedPreview=await nativeFrame(correctedProject,1_500_000)
  expect(correctedPreview.equals(await nativeFrame(beforeImport,1_500_000))).toBe(false)
  expect((await exportFrames(correctedProject,1_500_000,1_500_001)).equals(correctedPreview)).toBe(true)
  expect((await rpc('export_captions',{format:'vtt',composition_id:'unused'})).body).toContain('Исправлено &lt;&amp;&gt;\nSecond line')
  await expect(textEditor.getByRole('button',{name:'Сохранить текст',exact:true})).toBeDisabled()
  await page.getByRole('button',{name:'Undo nested captions',exact:true}).click()
  expect(JSON.parse(await nestedOutput.innerText())).toEqual(beforeImport)
  await expect(textInput).toHaveValue('unused: Inner caption')
  await textInput.fill('Unsaved draft')
  const conflictSnapshot=await rpc('get_project',{})
  await rpc('merge_captions',{expectedProjectHash:conflictSnapshot.projectHash,layer_ids:unusedLane.clips.map((clip:{id:string})=>clip.id)})
  await expect(textInput).toHaveValue('Unsaved draft')
  await expect(textEditor.getByRole('alert')).toContainText('Реплика изменилась')
  await expect(textEditor.getByRole('button',{name:'Сохранить текст',exact:true})).toBeDisabled()
  await textEditor.getByRole('button',{name:'Сбросить изменения текста',exact:true}).click()
  await expect(textInput).toHaveValue('unused: Inner caption\nunused: Adjacent caption')
  await rpc('undo',{})
  expect(JSON.parse(await nestedOutput.innerText())).toEqual(beforeImport)
  expect(JSON.parse(await documentOutput.innerText())).toEqual(packed)
  await page.getByLabel('Контрольная точка',{exact:true}).fill('Native point')
  await page.getByRole('button',{name:'Сохранить точку',exact:true}).click()
  await expect(page.getByText('Native point',{exact:true})).toBeVisible()
  await expect(page.getByText('Ordinary point',{exact:true})).toHaveCount(0)
  const nativePoints=await rpc('list_checkpoints',{})
  expect(nativePoints).toMatchObject([{label:'Native point',actor:'user'}])
  expect(Object.keys(nativePoints[0]).sort()).toEqual(['actor','created_at','id','label'])
  const checkpointDocument=JSON.parse(await nestedOutput.innerText())
  const checkpointContext=await rpc('get_project',{})
  await rpc('restyle_captions',{expectedProjectHash:checkpointContext.projectHash,font_size_px:77})
  const styledAfterPoint=JSON.parse(await nestedOutput.innerText())
  const pointRow=page.getByText('Native point',{exact:true}).locator('..')
  const restoring=page.waitForResponse(response=>new URL(response.url()).pathname==='/api/compositions/nested-durations')
  await pointRow.getByRole('button',{name:'Восстановить',exact:true}).click()
  expect((await restoring).status()).toBe(200)
  await expect.poll(async()=>JSON.parse(await nestedOutput.innerText())).toEqual(checkpointDocument)
  await rpc('undo',{})
  expect(JSON.parse(await nestedOutput.innerText())).toEqual(styledAfterPoint)
  await rpc('redo',{})
  expect(JSON.parse(await nestedOutput.innerText())).toEqual(checkpointDocument)
  await pointRow.getByRole('button',{name:'Удалить точку',exact:true}).click()
  await expect(page.getByText('Native point',{exact:true})).toHaveCount(0)
  expect(await rpc('list_checkpoints',{})).toEqual([])
  expect(JSON.parse(await documentOutput.innerText())).toEqual(packed)
  expect(errors).toEqual([])
})

