test('native multiline text alignment renders distinct frames and survives Undo and Redo',async({page,request})=>{
 const username='native-alignment-browser',password='native-alignment-password'
 const registered=await request.post('/api/auth/register',{data:{username,password}});expect(registered.status()).toBe(201)
 const {token}=await registered.json()
 const document={schemaVersion:1,root:'root',compositions:{root:{durationUs:2000000,content:{schemaVersion:1,timeBase:1000000,canvas:{width:320,height:180,fpsMilli:10000,background:{red:0,green:0,blue:0,alpha:1}},sources:{},tracks:[]},instances:[]}}}
 const created=await request.post('/api/composition-projects',{headers:{Authorization:`Bearer ${token}`},data:{schemaVersion:2,mode:'composition',name:'Native alignment',document}});expect(created.status()).toBe(201)
 const saved=await created.json(),mcpToken=process.env.VIDEO_KADR_MCP_TOKEN,backend=process.env.REAL_COMPOSITION_BACKEND_URL
 if(!mcpToken||!backend)throw new Error('Real MCP environment required')
 await page.goto('/');await page.getByRole('button',{name:'Multitrack',exact:true}).click()
 await page.getByLabel('Имя пользователя',{exact:true}).fill(username);await page.getByLabel('Пароль',{exact:true}).fill(password);await page.getByRole('button',{name:'Войти',exact:true}).click()
 await expect(page.getByLabel('Сохранённые композиции')).toBeEnabled();await page.getByLabel('Сохранённые композиции').selectOption(saved.id)
 await expect(page.getByRole('button',{name:'Вернуться к локальному монтажу',exact:true})).toBeVisible()
 await page.locator('summary',{hasText:'Агент и история'}).click();await page.getByLabel('Ключ подключения').fill(mcpToken);await page.getByRole('button',{name:'Подключить агента',exact:true}).click()
 await expect(page.getByRole('button',{name:'Отключить агента',exact:true})).toBeVisible()
 let id=0
 const rpc=async(name:string,args:Record<string,unknown>={})=>{
  const response=await request.post(`${backend}/mcp`,{headers:{Authorization:`Bearer ${mcpToken}`},data:{jsonrpc:'2.0',id:++id,method:'tools/call',params:{name,arguments:args}}})
  expect(response.status()).toBe(200);const body=await response.json();expect(body.result.isError).toBeFalsy();return JSON.parse(body.result.content[0].text)
 }
 const initial=await rpc('get_project')
 expect(initial.nativeBatch.textStylePatchFields).toContain('align')
 const left=await rpc('apply_batch',{expectedProjectHash:initial.projectHash,operations:[{op:'add_track',track:{id:'titles',kind:'text',name:'Titles',hidden:false,locked:false,clips:[]}},{op:'add_layer',trackId:'titles',clip:{id:'title',kind:'text',timelineStartTicks:0,durationTicks:2000000,text:'MMMMMMMM\nM',x:0,y:0,opacity:1,style:{fontSizePx:24,color:'#FFFFFFFF',align:'left'}}}]})
 const frame=async(project:unknown)=>{const response=await request.post('/api/compositions/nested-preview',{headers:{Authorization:`Bearer ${token}`},data:{project,compositionId:'root',timeUs:500000,renderedOutputs:{}}});expect(response.status()).toBe(200);const bytes=await response.body();expect(bytes.length).toBe(320*180*4);return bytes}
 const leftFrame=await frame(left.document)
 const centerOps=[{op:'update_layer',clipId:'title',patch:{style:{align:'center'}}}]
 const preview=await rpc('dry_run',{expectedProjectHash:left.projectHash,operations:centerOps})
 expect((await rpc('get_project')).document).toEqual(left.document)
 const center=await rpc('apply_batch',{expectedProjectHash:left.projectHash,operations:centerOps});expect(center.document).toEqual(preview.document)
 expect(center.document.compositions.root.content.tracks[0].clips[0].style.align).toBe('center')
 const centerFrame=await frame(center.document);expect(centerFrame.equals(leftFrame)).toBe(false)
 const right=await rpc('apply_batch',{expectedProjectHash:center.projectHash,operations:[{op:'update_layer',clipId:'title',patch:{style:{align:'right'}}}]})
 const rightFrame=await frame(right.document);expect(rightFrame.equals(centerFrame)).toBe(false);expect(rightFrame.equals(leftFrame)).toBe(false)
 await rpc('undo');expect((await rpc('get_project')).document).toEqual(center.document)
 expect((await frame((await rpc('get_project')).document)).equals(centerFrame)).toBe(true)
 await rpc('redo');expect((await frame((await rpc('get_project')).document)).equals(rightFrame)).toBe(true)
})


