test('Concat custom fonts import as project resources and survive UI replacement and reopen',async({page,request})=>{
 const username='concat-font-browser',password='concat-font-password'
 const registered=await request.post('/api/auth/register',{data:{username,password}});expect(registered.status()).toBe(201)
 const {token}=await registered.json(),mcpToken=process.env.VIDEO_KADR_MCP_TOKEN,backend=process.env.REAL_COMPOSITION_BACKEND_URL
 if(!mcpToken||!backend)throw new Error('Real MCP environment required')
 const font=Buffer.from(await readFile(new URL('../../backend/vendor/concat-text/fonts/Inter-Regular.ttf',import.meta.url)))
 for(const [from,to] of [[Buffer.from('Inter'),Buffer.from('KadrX')],[Buffer.from([... 'Inter'].flatMap(c=>[0,c.charCodeAt(0)])),Buffer.from([... 'KadrX'].flatMap(c=>[0,c.charCodeAt(0)]))]]){let at=0;while((at=font.indexOf(from!,at))>=0){to!.copy(font,at);at+=from!.length}}
 const source={version:1,name:'Owned custom fonts',media:[],fonts:[{family:'KadrX',path:'/never/open/KadrX.ttf'}],activeTimelineId:'TL',timelines:[{id:'TL',video:{width:320,height:180,rateNum:10,rateDen:1},tracks:[{id:'titles'}],clips:[{id:'title',trackId:'titles',kind:'text',start:0,duration:2,text:{content:'Project fonts',fontFamily:'KadrX',fontSize:0.2,fontWeight:400,shadow:false}}]}]}
 await page.goto('/');await page.getByRole('button',{name:'Multitrack',exact:true}).click()
 await page.getByLabel('Имя пользователя',{exact:true}).fill(username);await page.getByLabel('Пароль',{exact:true}).fill(password);await page.getByRole('button',{name:'Войти',exact:true}).click()
 await page.locator('summary',{hasText:'Импорт проекта Concat'}).click()
 await page.getByLabel('Файл проекта Concat',{exact:true}).setInputFiles({name:'owned-font-project.json',mimeType:'application/json',buffer:Buffer.from(JSON.stringify(source))})
 await expect(page.getByRole('button',{name:'Проверить импорт Concat',exact:true})).toBeDisabled()
 await page.getByRole('button',{name:'Системная замена шрифта Concat /never/open/KadrX.ttf',exact:true}).click();await expect(page.getByRole('button',{name:'Проверить импорт Concat',exact:true})).toBeEnabled()
 await page.getByLabel('Файл шрифта Concat /never/open/KadrX.ttf',{exact:true}).setInputFiles({name:'owned-custom.ttf',mimeType:'font/ttf',buffer:font})
 await expect(page.getByText('owned-custom.ttf',{exact:true})).toBeVisible();await expect(page.getByRole('button',{name:'Проверить импорт Concat',exact:true})).toBeEnabled();await page.getByRole('button',{name:'Проверить импорт Concat',exact:true}).click()
 await expect(page.getByRole('button',{name:'Открыть импорт как новый проект',exact:true})).toBeVisible();await page.getByRole('button',{name:'Открыть импорт как новый проект',exact:true}).click()
 await expect(page.getByRole('button',{name:'Вернуться к локальному монтажу',exact:true})).toBeVisible()
 await page.locator('summary',{hasText:'Агент и история'}).click();await page.getByLabel('Ключ подключения').fill(mcpToken);await page.getByRole('button',{name:'Подключить агента',exact:true}).click();await expect(page.getByRole('button',{name:'Отключить агента',exact:true})).toBeVisible()
 let id=0
 const rpc=async(name:string,args:Record<string,unknown>={})=>{const response=await request.post(`${backend}/mcp`,{headers:{Authorization:`Bearer ${mcpToken}`},data:{jsonrpc:'2.0',id:++id,method:'tools/call',params:{name,arguments:args}}});expect(response.status()).toBe(200);const body=await response.json();expect(body.result.isError).toBeFalsy();return JSON.parse(body.result.content[0].text)}
 const initial=await rpc('get_project'),scope=initial.document.root
 expect(initial.document.fonts).toEqual([{family:'KadrX',data:font.toString('base64')}])
 const frame=async(project:unknown)=>{const response=await request.post('/api/compositions/nested-preview',{headers:{Authorization:`Bearer ${token}`},data:{project,compositionId:scope,timeUs:500000,renderedOutputs:{}}});expect(response.status()).toBe(200);const bytes=await response.body();expect(bytes.length).toBe(320*180*4);return bytes}
 const ownedFrame=await frame(initial.document),fallback=structuredClone(initial.document);delete fallback.fonts
 expect((await frame(fallback)).equals(ownedFrame)).toBe(false)
 await page.locator('summary',{hasText:'Шрифты всего проекта'}).click()
 await page.getByRole('button',{name:'Удалить файл шрифта KadrX 1',exact:true}).click()
 await expect.poll(async()=>((await rpc('get_project')).document.fonts??[]).length).toBe(0)
 const removedFont=await rpc('get_project');expect(removedFont.document.compositions[scope].content.tracks[0].clips[0].concatTitle.fontFamily).toBe('KadrX');expect((await frame(removedFont.document)).equals(await frame(fallback))).toBe(true)
 await rpc('undo');expect((await rpc('get_project')).document).toEqual(initial.document);expect((await frame(initial.document)).equals(ownedFrame)).toBe(true)
 await rpc('redo');await page.getByLabel('Добавить файл шрифта в проект',{exact:true}).setInputFiles({name:'restored-custom.ttf',mimeType:'font/ttf',buffer:font})
 await expect.poll(async()=>((await rpc('get_project')).document.fonts??[]).length).toBe(1)
 expect((await rpc('get_project')).document).toEqual(initial.document);expect((await frame((await rpc('get_project')).document)).equals(ownedFrame)).toBe(true)
 await expect(page.getByLabel('Добавить файл шрифта в проект',{exact:true})).toBeEnabled()
 const duplicateHistory=await rpc('get_history');await page.getByLabel('Добавить файл шрифта в проект',{exact:true}).setInputFiles({name:'duplicate-custom.ttf',mimeType:'font/ttf',buffer:font});await expect(page.getByLabel('Добавить файл шрифта в проект',{exact:true})).toBeEnabled();expect((await rpc('get_history')).undoCount).toBe(duplicateHistory.undoCount)
 await expect(page.getByRole('combobox',{name:'Исходный шрифт проекта',exact:true})).toBeVisible()
 await page.getByRole('combobox',{name:'Исходный шрифт проекта',exact:true}).selectOption('KadrX/Regular')
 await page.getByRole('textbox',{name:'Новое семейство шрифта проекта',exact:true}).fill('Hanken Grotesk');await page.getByRole('textbox',{name:'Новое начертание шрифта проекта',exact:true}).fill('Bold Italic');await page.getByRole('button',{name:'Заменить шрифт во всём проекте',exact:true}).click()
 await expect.poll(async()=>(await rpc('get_project')).document.compositions[scope].content.tracks[0].clips[0].concatTitle.fontFamily).toBe('Hanken Grotesk')
 const replaced=await rpc('get_project'),replacedFrame=await frame(replaced.document);expect(replacedFrame.equals(ownedFrame)).toBe(false)
 await expect(page.getByRole('combobox',{name:'Исходный шрифт проекта',exact:true})).toHaveValue('');await expect(page.getByRole('button',{name:'Заменить шрифт во всём проекте',exact:true})).toBeDisabled()
 expect(replaced.document.compositions[scope].content.tracks[0].clips[0].concatTitle).toMatchObject({fontWeight:700,italic:true})
 await rpc('undo');expect((await rpc('get_project')).document).toEqual(initial.document);expect((await frame(initial.document)).equals(ownedFrame)).toBe(true)
 await rpc('redo');expect((await rpc('get_project')).document).toEqual(replaced.document)
 const savedResponse=await request.post('/api/composition-projects',{headers:{Authorization:`Bearer ${token}`},data:{schemaVersion:2,mode:'composition',name:'Portable fonts',document:replaced.document}});expect(savedResponse.status()).toBe(201)
 const saved=await savedResponse.json(),response=await request.get(`/api/composition-projects/${saved.id}`,{headers:{Authorization:`Bearer ${token}`}});expect(response.status()).toBe(200)
 const restored=await response.json();expect(restored.document).toEqual(replaced.document);expect((await frame(restored.document)).equals(replacedFrame)).toBe(true)
})

